/* usb_cdc_hal: USB CDC-ACM virtual COM port on the STM32F405ZG OTG_FS with ST's official stack, unmodified:
 * STM32CubeF4 HAL PCD + LL USB driver and the ST USB Device Library (usbd_core / usbd_ctlreq / usbd_ioreq +
 * the CDC class, vendored under ../vendor/STM32CubeF4/Middlewares/ST/STM32_USB_Device_Library).
 *
 * Clock:  HSE 8 MHz -> PLL (M 8, N 336, P 2, Q 7): SYSCLK = HCLK = 168 MHz, PLL48CLK = 48 MHz (USB), APB1 42 MHz,
 *         APB2 84 MHz (SystemClock_Config as generated by STM32CubeMX).
 * USB:    OTG_FS device, embedded FS PHY on PA11 (DM) / PA12 (DP), AF10; VBUS sensing off (NOVBUSSENS, as CubeMX
 *         generates for boards without the PA9 VBUS connection); the glue below is CubeMX's usbd_conf.c /
 *         usbd_desc.c / usbd_cdc_if.c, condensed: FIFO split RX 0x80, TX0 0x40, TX1 0x80 words.
 * App:    when the host opens the port (SET_CONTROL_LINE_STATE with DTR) it prints "HAL CDC ready\r\n"; every packet
 *         received is echoed back upper-cased.  Exported counters for tests: cdc_dtr, cdc_rx_bytes, cdc_tx_packets,
 *         line_coding_baud, usb_suspended (1 while the bus is suspended), usb_resumes.
 * Run:    chipem run --board boards/stm32_usb_cdc_hal.yaml --for 400ms
 */
#include "stm32f4xx_hal.h"
#include "usbd_core.h"
#include "usbd_cdc.h"

PCD_HandleTypeDef hpcd_USB_OTG_FS;
USBD_HandleTypeDef hUsbDeviceFS;

volatile uint32_t cdc_dtr, cdc_rx_bytes, cdc_tx_packets, line_coding_baud, usb_suspended, usb_resumes;
static volatile uint32_t want_banner;
static uint8_t rx_buf[CDC_DATA_FS_MAX_PACKET_SIZE];
static uint8_t tx_buf[CDC_DATA_FS_MAX_PACKET_SIZE];
static uint8_t line_coding[7] = {0x00, 0xC2, 0x01, 0x00, 0, 0, 8};

static void SystemClock_Config(void);
static void Error_Handler(void);

/* ------------------------------------------------------------------ interrupts */
void SysTick_Handler(void) { HAL_IncTick(); }
void OTG_FS_IRQHandler(void) { HAL_PCD_IRQHandler(&hpcd_USB_OTG_FS); }

/* ------------------------------------------------------------------ PCD MSP (pins, clock, NVIC) */
void HAL_PCD_MspInit(PCD_HandleTypeDef *pcdHandle)
{
    GPIO_InitTypeDef g = {0};
    if (pcdHandle->Instance != USB_OTG_FS)
        return;
    __HAL_RCC_GPIOA_CLK_ENABLE();
    g.Pin = GPIO_PIN_11 | GPIO_PIN_12;
    g.Mode = GPIO_MODE_AF_PP;
    g.Pull = GPIO_NOPULL;
    g.Speed = GPIO_SPEED_FREQ_VERY_HIGH;
    g.Alternate = GPIO_AF10_OTG_FS;
    HAL_GPIO_Init(GPIOA, &g);
    __HAL_RCC_USB_OTG_FS_CLK_ENABLE();
    HAL_NVIC_SetPriority(OTG_FS_IRQn, 0, 0);
    HAL_NVIC_EnableIRQ(OTG_FS_IRQn);
}

/* ------------------------------------------------------------------ PCD callbacks -> USB device library */
void HAL_PCD_SetupStageCallback(PCD_HandleTypeDef *hpcd) { USBD_LL_SetupStage(hpcd->pData, (uint8_t *)hpcd->Setup); }
void HAL_PCD_DataOutStageCallback(PCD_HandleTypeDef *hpcd, uint8_t epnum)
{
    USBD_LL_DataOutStage(hpcd->pData, epnum, hpcd->OUT_ep[epnum].xfer_buff);
}
void HAL_PCD_DataInStageCallback(PCD_HandleTypeDef *hpcd, uint8_t epnum)
{
    USBD_LL_DataInStage(hpcd->pData, epnum, hpcd->IN_ep[epnum].xfer_buff);
}
void HAL_PCD_SOFCallback(PCD_HandleTypeDef *hpcd) { USBD_LL_SOF(hpcd->pData); }
void HAL_PCD_ResetCallback(PCD_HandleTypeDef *hpcd)
{
    USBD_LL_SetSpeed(hpcd->pData, USBD_SPEED_FULL);
    USBD_LL_Reset(hpcd->pData);
}
void HAL_PCD_SuspendCallback(PCD_HandleTypeDef *hpcd)
{
    USBD_LL_Suspend(hpcd->pData);
    __HAL_PCD_GATE_PHYCLOCK(hpcd);
    usb_suspended = 1;
}
void HAL_PCD_ResumeCallback(PCD_HandleTypeDef *hpcd)
{
    __HAL_PCD_UNGATE_PHYCLOCK(hpcd);
    USBD_LL_Resume(hpcd->pData);
    usb_suspended = 0;
    usb_resumes++;
}
void HAL_PCD_ISOOUTIncompleteCallback(PCD_HandleTypeDef *hpcd, uint8_t epnum) { USBD_LL_IsoOUTIncomplete(hpcd->pData, epnum); }
void HAL_PCD_ISOINIncompleteCallback(PCD_HandleTypeDef *hpcd, uint8_t epnum) { USBD_LL_IsoINIncomplete(hpcd->pData, epnum); }
void HAL_PCD_ConnectCallback(PCD_HandleTypeDef *hpcd) { USBD_LL_DevConnected(hpcd->pData); }
void HAL_PCD_DisconnectCallback(PCD_HandleTypeDef *hpcd) { USBD_LL_DevDisconnected(hpcd->pData); }

/* ------------------------------------------------------------------ USB device library low layer (usbd_conf.c) */
static USBD_StatusTypeDef status(HAL_StatusTypeDef s)
{
    return s == HAL_OK ? USBD_OK : s == HAL_BUSY ? USBD_BUSY : USBD_FAIL;
}

USBD_StatusTypeDef USBD_LL_Init(USBD_HandleTypeDef *pdev)
{
    hpcd_USB_OTG_FS.pData = pdev;
    pdev->pData = &hpcd_USB_OTG_FS;
    hpcd_USB_OTG_FS.Instance = USB_OTG_FS;
    hpcd_USB_OTG_FS.Init.dev_endpoints = 4;
    hpcd_USB_OTG_FS.Init.speed = PCD_SPEED_FULL;
    hpcd_USB_OTG_FS.Init.dma_enable = DISABLE;
    hpcd_USB_OTG_FS.Init.phy_itface = PCD_PHY_EMBEDDED;
    hpcd_USB_OTG_FS.Init.Sof_enable = DISABLE;
    hpcd_USB_OTG_FS.Init.low_power_enable = DISABLE;
    hpcd_USB_OTG_FS.Init.lpm_enable = DISABLE;
    hpcd_USB_OTG_FS.Init.vbus_sensing_enable = DISABLE;
    hpcd_USB_OTG_FS.Init.use_dedicated_ep1 = DISABLE;
    if (HAL_PCD_Init(&hpcd_USB_OTG_FS) != HAL_OK)
        Error_Handler();
    HAL_PCDEx_SetRxFiFo(&hpcd_USB_OTG_FS, 0x80);
    HAL_PCDEx_SetTxFiFo(&hpcd_USB_OTG_FS, 0, 0x40);
    HAL_PCDEx_SetTxFiFo(&hpcd_USB_OTG_FS, 1, 0x80);
    return USBD_OK;
}
USBD_StatusTypeDef USBD_LL_DeInit(USBD_HandleTypeDef *pdev) { return status(HAL_PCD_DeInit(pdev->pData)); }
USBD_StatusTypeDef USBD_LL_Start(USBD_HandleTypeDef *pdev) { return status(HAL_PCD_Start(pdev->pData)); }
USBD_StatusTypeDef USBD_LL_Stop(USBD_HandleTypeDef *pdev) { return status(HAL_PCD_Stop(pdev->pData)); }
USBD_StatusTypeDef USBD_LL_OpenEP(USBD_HandleTypeDef *pdev, uint8_t ep_addr, uint8_t ep_type, uint16_t ep_mps)
{
    return status(HAL_PCD_EP_Open(pdev->pData, ep_addr, ep_mps, ep_type));
}
USBD_StatusTypeDef USBD_LL_CloseEP(USBD_HandleTypeDef *pdev, uint8_t ep_addr) { return status(HAL_PCD_EP_Close(pdev->pData, ep_addr)); }
USBD_StatusTypeDef USBD_LL_FlushEP(USBD_HandleTypeDef *pdev, uint8_t ep_addr) { return status(HAL_PCD_EP_Flush(pdev->pData, ep_addr)); }
USBD_StatusTypeDef USBD_LL_StallEP(USBD_HandleTypeDef *pdev, uint8_t ep_addr) { return status(HAL_PCD_EP_SetStall(pdev->pData, ep_addr)); }
USBD_StatusTypeDef USBD_LL_ClearStallEP(USBD_HandleTypeDef *pdev, uint8_t ep_addr) { return status(HAL_PCD_EP_ClrStall(pdev->pData, ep_addr)); }
uint8_t USBD_LL_IsStallEP(USBD_HandleTypeDef *pdev, uint8_t ep_addr)
{
    PCD_HandleTypeDef *h = pdev->pData;
    return (ep_addr & 0x80U) ? h->IN_ep[ep_addr & 0x7FU].is_stall : h->OUT_ep[ep_addr & 0x7FU].is_stall;
}
USBD_StatusTypeDef USBD_LL_SetUSBAddress(USBD_HandleTypeDef *pdev, uint8_t dev_addr)
{
    return status(HAL_PCD_SetAddress(pdev->pData, dev_addr));
}
USBD_StatusTypeDef USBD_LL_Transmit(USBD_HandleTypeDef *pdev, uint8_t ep_addr, uint8_t *pbuf, uint32_t size)
{
    return status(HAL_PCD_EP_Transmit(pdev->pData, ep_addr, pbuf, size));
}
USBD_StatusTypeDef USBD_LL_PrepareReceive(USBD_HandleTypeDef *pdev, uint8_t ep_addr, uint8_t *pbuf, uint32_t size)
{
    return status(HAL_PCD_EP_Receive(pdev->pData, ep_addr, pbuf, size));
}
uint32_t USBD_LL_GetRxDataSize(USBD_HandleTypeDef *pdev, uint8_t ep_addr) { return HAL_PCD_EP_GetRxCount(pdev->pData, ep_addr); }
void USBD_LL_Delay(uint32_t Delay) { HAL_Delay(Delay); }

static uint32_t class_mem[(sizeof(USBD_CDC_HandleTypeDef) / 4) + 1];
void *USBD_static_malloc(uint32_t size) { (void)size; return class_mem; }
void USBD_static_free(void *p) { (void)p; }

/* ------------------------------------------------------------------ descriptors (usbd_desc.c) */
#define USBD_VID 0x0483
#define USBD_PID 0x5740
static uint8_t dev_desc[USB_LEN_DEV_DESC] = {
    0x12, USB_DESC_TYPE_DEVICE, 0x00, 0x02, 0x02, 0x02, 0x00, USB_MAX_EP0_SIZE,
    LOBYTE(USBD_VID), HIBYTE(USBD_VID), LOBYTE(USBD_PID), HIBYTE(USBD_PID), 0x00, 0x02,
    USBD_IDX_MFC_STR, USBD_IDX_PRODUCT_STR, USBD_IDX_SERIAL_STR, USBD_MAX_NUM_CONFIGURATION
};
static uint8_t lang_desc[USB_LEN_LANGID_STR_DESC] = {USB_LEN_LANGID_STR_DESC, USB_DESC_TYPE_STRING, 0x09, 0x04};
static uint8_t str_desc[USBD_MAX_STR_DESC_SIZ];

static uint8_t *d_device(USBD_SpeedTypeDef s, uint16_t *len) { (void)s; *len = sizeof dev_desc; return dev_desc; }
static uint8_t *d_lang(USBD_SpeedTypeDef s, uint16_t *len) { (void)s; *len = sizeof lang_desc; return lang_desc; }
static uint8_t *d_str(const char *text, uint16_t *len) { USBD_GetString((uint8_t *)text, str_desc, len); return str_desc; }
static uint8_t *d_mfc(USBD_SpeedTypeDef s, uint16_t *len) { (void)s; return d_str("STMicroelectronics", len); }
static uint8_t *d_product(USBD_SpeedTypeDef s, uint16_t *len) { (void)s; return d_str("STM32 HAL Virtual ComPort", len); }
static uint8_t *d_serial(USBD_SpeedTypeDef s, uint16_t *len) { (void)s; return d_str("CHIPEM0001", len); }
static uint8_t *d_config(USBD_SpeedTypeDef s, uint16_t *len) { (void)s; return d_str("CDC Config", len); }
static uint8_t *d_intf(USBD_SpeedTypeDef s, uint16_t *len) { (void)s; return d_str("CDC Interface", len); }

USBD_DescriptorsTypeDef FS_Desc = {d_device, d_lang, d_mfc, d_product, d_serial, d_config, d_intf};

/* ------------------------------------------------------------------ CDC interface (usbd_cdc_if.c) */
static int8_t cdc_init(void)
{
    USBD_CDC_SetTxBuffer(&hUsbDeviceFS, tx_buf, 0);
    USBD_CDC_SetRxBuffer(&hUsbDeviceFS, rx_buf);
    return USBD_OK;
}
static int8_t cdc_deinit(void) { return USBD_OK; }
static int8_t cdc_control(uint8_t cmd, uint8_t *pbuf, uint16_t length)
{
    (void)length;
    switch (cmd) {
    case CDC_SET_LINE_CODING:
        for (int i = 0; i < 7; i++)
            line_coding[i] = pbuf[i];
        line_coding_baud = (uint32_t)pbuf[0] | ((uint32_t)pbuf[1] << 8) | ((uint32_t)pbuf[2] << 16)
                         | ((uint32_t)pbuf[3] << 24);
        break;
    case CDC_GET_LINE_CODING:
        for (int i = 0; i < 7; i++)
            pbuf[i] = line_coding[i];
        break;
    case CDC_SET_CONTROL_LINE_STATE: {
        USBD_SetupReqTypedef *req = (USBD_SetupReqTypedef *)pbuf;
        uint32_t dtr = req->wValue & 1u;
        if (dtr && !cdc_dtr)
            want_banner = 1;
        cdc_dtr = dtr;
        break;
    }
    default:
        break;
    }
    return USBD_OK;
}
static int8_t cdc_receive(uint8_t *buf, uint32_t *len)
{
    USBD_CDC_HandleTypeDef *h = hUsbDeviceFS.pClassData;
    cdc_rx_bytes += *len;
    if (h != NULL && h->TxState == 0U) {
        uint32_t n = *len;
        for (uint32_t i = 0; i < n; i++)
            tx_buf[i] = (buf[i] >= 'a' && buf[i] <= 'z') ? (uint8_t)(buf[i] - 32) : buf[i];
        USBD_CDC_SetTxBuffer(&hUsbDeviceFS, tx_buf, n);
        if (USBD_CDC_TransmitPacket(&hUsbDeviceFS) == USBD_OK)
            cdc_tx_packets++;
    }
    USBD_CDC_SetRxBuffer(&hUsbDeviceFS, rx_buf);
    USBD_CDC_ReceivePacket(&hUsbDeviceFS);
    return USBD_OK;
}
static int8_t cdc_tx_done(uint8_t *buf, uint32_t *len, uint8_t epnum)
{
    (void)buf; (void)len; (void)epnum;
    return USBD_OK;
}
static USBD_CDC_ItfTypeDef cdc_fops = {cdc_init, cdc_deinit, cdc_control, cdc_receive, cdc_tx_done};

/* ------------------------------------------------------------------ main */
int main(void)
{
    HAL_Init();
    SystemClock_Config();
    if (USBD_Init(&hUsbDeviceFS, &FS_Desc, DEVICE_FS) != USBD_OK)
        Error_Handler();
    if (USBD_RegisterClass(&hUsbDeviceFS, &USBD_CDC) != USBD_OK)
        Error_Handler();
    if (USBD_CDC_RegisterInterface(&hUsbDeviceFS, &cdc_fops) != USBD_OK)
        Error_Handler();
    if (USBD_Start(&hUsbDeviceFS) != USBD_OK)
        Error_Handler();
    for (;;) {
        if (want_banner) {
            static const char banner[] = "HAL CDC ready\r\n";
            USBD_CDC_HandleTypeDef *h = hUsbDeviceFS.pClassData;
            if (h != NULL && h->TxState == 0U) {
                want_banner = 0;
                for (uint32_t i = 0; i < sizeof banner - 1; i++)
                    tx_buf[i] = (uint8_t)banner[i];
                __disable_irq();
                USBD_CDC_SetTxBuffer(&hUsbDeviceFS, tx_buf, sizeof banner - 1);
                if (USBD_CDC_TransmitPacket(&hUsbDeviceFS) == USBD_OK)
                    cdc_tx_packets++;
                __enable_irq();
            }
        }
        __WFI();
    }
}

static void SystemClock_Config(void)
{
    RCC_OscInitTypeDef osc = {0};
    RCC_ClkInitTypeDef clk = {0};
    __HAL_RCC_PWR_CLK_ENABLE();
    __HAL_PWR_VOLTAGESCALING_CONFIG(PWR_REGULATOR_VOLTAGE_SCALE1);
    osc.OscillatorType = RCC_OSCILLATORTYPE_HSE;
    osc.HSEState = RCC_HSE_ON;
    osc.PLL.PLLState = RCC_PLL_ON;
    osc.PLL.PLLSource = RCC_PLLSOURCE_HSE;
    osc.PLL.PLLM = 8;
    osc.PLL.PLLN = 336;
    osc.PLL.PLLP = RCC_PLLP_DIV2;
    osc.PLL.PLLQ = 7;
    if (HAL_RCC_OscConfig(&osc) != HAL_OK)
        Error_Handler();
    clk.ClockType = RCC_CLOCKTYPE_HCLK | RCC_CLOCKTYPE_SYSCLK | RCC_CLOCKTYPE_PCLK1 | RCC_CLOCKTYPE_PCLK2;
    clk.SYSCLKSource = RCC_SYSCLKSOURCE_PLLCLK;
    clk.AHBCLKDivider = RCC_SYSCLK_DIV1;
    clk.APB1CLKDivider = RCC_HCLK_DIV4;
    clk.APB2CLKDivider = RCC_HCLK_DIV2;
    if (HAL_RCC_ClockConfig(&clk, FLASH_LATENCY_5) != HAL_OK)
        Error_Handler();
}

static void Error_Handler(void)
{
    __disable_irq();
    for (;;) { }
}
